    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        for (int i = 0; i < 256 && remaining > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                remaining--;
