}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[j] will hold all possible sums of subsets of size j
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate j from current max down to 1
        for (int j = Math.min(n, n); j >= 1; j--) {
            if (dp[j - 1].isEmpty()) continue;
            for (int prevSum : dp[j - 1]) {
                dp[j].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((long) totalSum * k % n != 0) continue;
        int target = (int) ((long) totalSum * k / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

