        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                insertions++; // need an opening bracket before this ')'
            }
        }
    }
    insertions += balance; // close remaining '('
    return insertions;
}

