        return 0;
    }
    int maxEndingHere = nums[0];
    int minEndingHere = nums[0];
    int maxSum = nums[0];
    int minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEndingHere = Math.max(val, maxEndingHere + val);
        maxSum = Math.max(maxSum, maxEndingHere);
        minEndingHere = Math.min(val, minEndingHere + val);
        minSum = Math.min(minSum, minEndingHere);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    int count = 0;
    for (int f : small) {
        count++;
        if (count == k) return f;
    }
    for (int f : large) {
        count++;
        if (count == k) return f;
    }
    return -1;
}

