public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // extra value needed beyond all 'a's
    // Increase characters from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

