public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;
    Queue<Long> queue = new LinkedList<>();

    // Handle single digit numbers
    for (int d = 0; d <= 9; d++) {
        if (d == 0) {
            if (low == 0) result.add(0);
            queue.offer(0L);
        } else {
            if (d >= low && d <= high) result.add(d);
            queue.offer((long) d);
        }
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        int lastDigit = (int) (num % 10);

        // Next possible digits
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (int nd : nextDigits) {
            if (nd < 0 || nd > 9) continue;
            long newNum = num * 10 + nd;
            if (newNum > high) continue;
            if (newNum >= low) result.add((int) newNum);
            queue.offer(newNum);
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

