public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    long absValue = Math.abs((long) n);
    String s = Long.toString(absValue);
    int len = s.length();
    if (len <= 3) {
        return n < 0 ? "-" + s : s;
    }
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }
    StringBuilder sb = new StringBuilder();
    sb.append(s.substring(0, firstGroupLen));
    for (int i = firstGroupLen; i < len; i += 3) {
        sb.append('.').append(s.substring(i, i + 3));
    }
    if (n < 0) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
