        if (s % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = s - i;
                res[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = s - i;
                res[idx++] = mat[i][j];
            }
        }
    }
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    return buildStrobogrammatic(n, n);
}

private static List<String> buildStrobogrammatic(int currentLen, int totalLen) {
    if (currentLen == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (currentLen == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }

    List<String> prev = buildStrobogrammatic(currentLen - 2, totalLen);
    List<String> result = new ArrayList<>();

    for (String mid : prev) {
        // Add pairs
        result.add("1" + mid + "1");
        result.add("6" + mid + "9");
        result.add("8" + mid + "8");
        result.add("9" + mid + "6");
        // Add leading zero pair only if not the outermost layer
        if (currentLen != totalLen) {
            result.add("0" + mid + "0");
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int area2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    if (n <= 0) return res;
    int cur = 1;
    for (int i = 0; i < n; i++) {
        res.add(cur);
        if ((long) cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur++;
        } else {
            while (cur / 10 % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int val = dp[i - j * j] + 1;
            if (val < min) min = val;
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
